import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

public class fasta {
    private static final int IM = 139968;
    private static final int IA = 3877;
    private static final int IC = 29573;
    private static final int WIDTH = 60;
    private static final int LINES_PER_BUFFER = 16384;

    private static int seed = 42;

    private static final String ALU =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG"
          + "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAG"
          + "ACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAA"
          + "TACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCC"
          + "AGCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGG"
          + "GAGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTC"
          + "CAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    private static byte[] makeLookup(String symbols, double[] probabilities) {
        double[] cumulative = new double[probabilities.length];
        double sum = 0.0;
        for (int i = 0; i < probabilities.length; i++) {
            sum += probabilities[i];
            cumulative[i] = sum;
        }

        byte[] lookup = new byte[IM];
        int symbol = 0;
        for (int value = 0; value < IM; value++) {
            double random = (double) value / IM;
            while (symbol + 1 < cumulative.length
                    && random >= cumulative[symbol]) {
                symbol++;
            }
            lookup[value] = (byte) symbols.charAt(symbol);
        }
        return lookup;
    }

    private static void writeRepeated(OutputStream out, long length)
            throws IOException {
        byte[] sequence = ALU.getBytes(StandardCharsets.US_ASCII);
        byte[] cycle = new byte[sequence.length * (WIDTH + 1)];

        int position = 0;
        int index = 0;
        for (int line = 0; line < sequence.length; line++) {
            for (int column = 0; column < WIDTH; column++) {
                cycle[position++] = sequence[index++];
                if (index == sequence.length) {
                    index = 0;
                }
            }
            cycle[position++] = '\n';
        }

        long basesPerCycle = (long) sequence.length * WIDTH;
        while (length >= basesPerCycle) {
            out.write(cycle);
            length -= basesPerCycle;
        }

        int fullLines = (int) (length / WIDTH);
        int bytes = fullLines * (WIDTH + 1);
        if (bytes != 0) {
            out.write(cycle, 0, bytes);
        }

        int tail = (int) (length % WIDTH);
        if (tail != 0) {
            out.write(cycle, bytes, tail);
            out.write('\n');
        }
    }

    private static void writeRandom(
            OutputStream out, long length, byte[] lookup, byte[] buffer)
            throws IOException {
        int state = seed;

        while (length >= WIDTH) {
            int lines = (int) Math.min(length / WIDTH, LINES_PER_BUFFER);
            int position = 0;

            for (int line = 0; line < lines; line++) {
                int end = position + WIDTH;
                while (position < end) {
                    state = (state * IA + IC) % IM;
                    buffer[position++] = lookup[state];
                }
                buffer[position++] = '\n';
            }

            out.write(buffer, 0, position);
            length -= (long) lines * WIDTH;
        }

        if (length != 0) {
            int position = 0;
            for (int i = 0; i < (int) length; i++) {
                state = (state * IA + IC) % IM;
                buffer[position++] = lookup[state];
            }
            buffer[position++] = '\n';
            out.write(buffer, 0, position);
        }

        seed = state;
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(args[0]);

        byte[] iub = makeLookup(
                "acgtBDHKMNRSVWY",
                new double[] {
                    0.27, 0.12, 0.12, 0.27,
                    0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
                    0.02, 0.02, 0.02, 0.02, 0.02
                });

        byte[] human = makeLookup(
                "acgt",
                new double[] {
                    0.3029549426680,
                    0.1979883004921,
                    0.1975473066391,
                    0.3015094502008
                });

        byte[] buffer = new byte[LINES_PER_BUFFER * (WIDTH + 1)];
        OutputStream out = new BufferedOutputStream(System.out, 1 << 16);

        out.write(">ONE Homo sapiens alu\n"
                .getBytes(StandardCharsets.US_ASCII));
        writeRepeated(out, 2L * n);

        out.write(">TWO IUB ambiguity codes\n"
                .getBytes(StandardCharsets.US_ASCII));
        writeRandom(out, 3L * n, iub, buffer);

        out.write(">THREE Homo sapiens frequency\n"
                .getBytes(StandardCharsets.US_ASCII));
        writeRandom(out, 5L * n, human, buffer);

        out.flush();
    }
}

